// 返回首个 >= x 的下标（0-based），不存在返回 -1；a 非递减
int lower_bound_idx(const vector<long long> &a, long long x) {
 int l = 0, r = (int)a.size() - 1, ans = -1;
 while (l <= r) {
 int mid = l + (r - l) / 2;
 if (a[mid] >= x) { ans = mid; r = mid - 1;}
 else l = mid + 1;
}
 return ans;
}
int main() {
 ios::sync_with_stdio(false);
 cin.tie(nullptr);
 int n;
 if (!(cin >> n)) return 0;
 vector<long long> a(n);
 for (int i = 0; i < n; ++i) cin >> a[i];
 long long x; cin >> x;
 cout << lower_bound_idx(a, x) << '\n';
 return 0;
}

