def merge_intervals(segs):
    '''合并重叠区间，返回合并后的区间列表（按左端点排序）。'''
    if not segs:
        return []
    segs = sorted(segs)
    res = [list(segs[0])]
    for l, r in segs[1:]:
        if l <= res[-1][1]:
            res[-1][1] = max(res[-1][1], r)
        else:
            res.append([l, r])
    return res


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n = data[0]
    segs = [(data[1 + 2 * i], data[2 + 2 * i]) for i in range(n)]
    out = merge_intervals(segs)
    sys.stdout.write('\n'.join(f'{l} {r}' for l, r in out))

