using namespace std;
using int64 = long long;
// 返回每个长度为 k 的滑动窗口的最大值
vector<int64> sliding_max(const vector<int64> &a, int k) {
    deque<int> dq;
    vector<int64> res;
    for (int i = 0; i < (int)a.size(); ++i) {
        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();
        dq.push_back(i);
        if (dq.front() <= i - k) dq.pop_front();
        if (i >= k - 1) res.push_back(a[dq.front()]);
    }
    return res;
}
