def is_valid(s):
    '''判断括号串是否合法。只含 ()[]{}。'''
    pairs = {')': '(', ']': '[', '}': '{'}
    st = []
    for ch in s:
        if ch in '([{':
            st.append(ch)
        elif ch in pairs:
            if not st or st.pop() != pairs[ch]:
                return False
    return not st


if __name__ == '__main__':
