// 判断括号串是否合法，只含 ()[]{}
bool is_valid(const string &s) {
    unordered_map<char,char> pairs = {{')','('},{']','['},{'}','{'}};
    vector<char> st;
    for (char ch : s) {
        if (ch == '(' || ch == '[' || ch == '{') st.push_back(ch);
        else if (pairs.count(ch)) {
            if (st.empty() || st.back() != pairs[ch]) return false;
            st.pop_back();
        }
    }
    return st.empty();
}
