struct Node { int val; Node *next; Node(int v): val(v), next(nullptr) {} };
// 原地反转链表，返回新头
Node* reverse_list(Node *head) {
    Node *prev = nullptr, *cur = head;
    while (cur) {
        Node *nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    return prev;
}
int main() {
