// 返回 {选 u 的最大值, 不选 u 的最大值}
pair<int64,int64> dfs(int u, int parent) {
    int64 rob = val[u], skip = 0;
    for (int w : g[u]) if (w != parent) {
        auto [r, s] = dfs(w, u);
        rob += s;
        skip += max(r, s);
    }
    return {rob, skip};
}
