    for (int i = 0; i < n - 1; ++i) {
        int u, v; cin >> u >> v;
        g[u].push_back(v); g[v].push_back(u);
    }
    if (n == 0) { cout << 0 << '\n'; return 0; }
    auto [r, s] = dfs(1, 0);
    cout << max(r, s) << '\n';
    return 0;
}

