class DSU:
    '''并查集：路径压缩 + 按秩合并。'''

    def __init__(self, n):
        self.fa = list(range(n + 1))
        self.rank = [0] * (n + 1)

    def find(self, x):
        while self.fa[x] != x:
            self.fa[x] = self.fa[self.fa[x]]
            x = self.fa[x]
        return x

    def union(self, a, b):
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.fa[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1


def components(n, edges):
    dsu = DSU(n)
    for u, v in edges:
        dsu.union(u, v)
    return len({dsu.find(i) for i in range(1, n + 1)})


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n, m = data[0], data[1]
    edges = [(data[2 + 2 * i], data[3 + 2 * i]) for i in range(m)]
    print(components(n, edges))

