#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int64 INF = (int64)4e18;
// 相邻两堆合并的最小总花费
int64 merge_stones(const vector<int64> &a) {
    int n = a.size();
    if (n <= 1) return 0;
    vector<int64> pre(n + 1, 0);
    for (int i = 0; i < n; ++i) pre[i + 1] = pre[i] + a[i];
    auto seg = [&](int i, int j) { return pre[j + 1] - pre[i]; };
    vector<vector<int64>> dp(n, vector<int64>(n, 0));
    for (int len = 2; len <= n; ++len)
        for (int i = 0; i + len - 1 < n; ++i) {
            int j = i + len - 1;
            int64 best = INF;
            for (int k = i; k < j; ++k)
                best = min(best, dp[i][k] + dp[k + 1][j] + seg(i, j));
            dp[i][j] = best;
        }
    return dp[0][n - 1];
}
