def count_no_four(n):
    '''统计 [0, n] 中十进制不含数字 4 的数的个数。'''
    s = str(n)

    @lru_cache(maxsize=None)
    def dfs(pos, tight):
        if pos == len(s):
            return 1
        limit = int(s[pos]) if tight else 9
        total = 0
        for d in range(limit + 1):
            if d == 4:
                continue
            total += dfs(pos + 1, tight and d == limit)
        return total

    return dfs(0, True)


if __name__ == '__main__':
    import sys
    n = int(sys.stdin.read().strip())
    print(count_no_four(n))

