#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
struct DSU {
    vector<int> fa;
    DSU(int n = 0) { fa.resize(n + 1); iota(fa.begin(), fa.end(), 0); }
    int find(int x) {
        while (fa[x] != x) { fa[x] = fa[fa[x]]; x = fa[x]; }
        return x;
    }
    bool unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return false;
        fa[rb] = ra;
        return true;
    }
};
// Kruskal：返回最小生成树权值，不连通返回 -1
int64 mst(int n, vector<tuple<int,int,int64>> edges) {
    sort(edges.begin(), edges.end(),
         [](const auto &a, const auto &b) { return get<2>(a) < get<2>(b); });
    DSU dsu(n);
    int64 total = 0;
    int cnt = 0;
    for (auto [u, v, w] : edges)
        if (dsu.unite(u, v)) {
            total += w;
            if (++cnt == n - 1) break;
        }
    return cnt == n - 1 ? total : -1;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
