from collections import deque


def is_bipartite(n, edges):
    '''判断无向图是否是二分图。节点 1..n。'''
    g = [[] for _ in range(n + 1)]
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)
    color = [0] * (n + 1)
    for s in range(1, n + 1):
        if color[s]:
            continue
        color[s] = 1
        q = deque([s])
        while q:
            u = q.popleft()
            for w in g[u]:
                if color[w] == 0:
                    color[w] = 3 - color[u]
                    q.append(w)
                elif color[w] == color[u]:
                    return False
    return True


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n, m = data[0], data[1]
    edges = [(data[2 + 2 * i], data[3 + 2 * i]) for i in range(m)]
    print('YES' if is_bipartite(n, edges) else 'NO')

