#include <bits/stdc++.h>
using namespace std;
// Manacher：返回最长回文子串（并列取起点最小）
string longest_palindrome(const string &s) {
    if (s.empty()) return "";
    string t = "#";
    for (char c : s) { t += c; t += '#'; }
    int n = t.size();
    vector<int> arm(n, 0);
    int center = 0, right = 0;
    int best_len = 1, best_start = 0;
    for (int i = 0; i < n; ++i) {
        int mirror = 2 * center - i;
        if (i < right) arm[i] = min(right - i, arm[mirror]);
        while (i - arm[i] - 1 >= 0 && i + arm[i] + 1 < n && t[i - arm[i] - 1] == t[i + arm[i] + 1])
            ++arm[i];
        if (i + arm[i] > right) { center = i; right = i + arm[i]; }
        int cur_len = arm[i];
        int cur_start = (i - arm[i]) / 2;
        if (cur_len > best_len || (cur_len == best_len && cur_start < best_start)) {
            best_len = cur_len;
            best_start = cur_start;
        }
    }
    return s.substr(best_start, best_len);
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    getline(cin, s);
    cout << longest_palindrome(s) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
using i128 = __int128_t;
// 快速幂：a^b % mod
int64 mod_pow(int64 a, int64 b, int64 mod) {
    int64 res = 1 % mod;
    a %= mod;
    while (b) {
        if (b & 1) res = (int64)((i128)res * a % mod);
        a = (int64)((i128)a * a % mod);
        b >>= 1;
    }
    return res;
}
int64 gcd_ll(int64 a, int64 b) {
    while (b) { int64 t = a % b; a = b; b = t; }
    return a;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int64 a, b, m, x, y;
    if (!(cin >> a >> b >> m >> x >> y)) return 0;
    cout << mod_pow(a, b, m) << '\n' << gcd_ll(x, y) << '\n';
    return 0;
}

template_python:
def sieve(n):
    '''线性筛：返回 n 以内的质数个数。'''
    if n < 2:
        return 0
    is_comp = [False] * (n + 1)
    primes = []
    for i in range(2, n + 1):
        if not is_comp[i]:
            primes.append(i)
        for p in primes:
            if i * p > n:
                break
            is_comp[i * p] = True
            if i % p == 0:
                break
    return len(primes)


def prepare_fact(limit, mod):
    fact = [1] * (limit + 1)
    for i in range(1, limit + 1):
        fact[i] = fact[i - 1] * i % mod
    inv_fact = [1] * (limit + 1)
    inv_fact[limit] = pow(fact[limit], mod - 2, mod)
    for i in range(limit, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % mod
    return fact, inv_fact


def comb(n, k, fact, inv_fact, mod):
    '''C(n,k) % mod，mod 为质数且 n,k < mod。'''
    if k < 0 or k > n:
        return 0
    return fact[n] * inv_fact[k] % mod * inv_fact[n - k] % mod


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n, q = data[0], data[1]
    pos = 2
    queries = []
    max_nk = 0
    for _ in range(q):
        nn, kk, p = data[pos], data[pos + 1], data[pos + 2]
        pos += 3
        queries.append((nn, kk, p))
        max_nk = max(max_nk, nn)
    out = [str(sieve(n))]
    for nn, kk, p in queries:
        fact, inv_fact = prepare_fact(nn, p)
        out.append(str(comb(nn, kk, fact, inv_fact, p)))
    sys.stdout.write('\n'.join(out))

