#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
// 线性筛：返回 n 以内质数个数
int sieve_count(int n) {
    if (n < 2) return 0;
    vector<int> primes;
    vector<bool> is_comp(n + 1, false);
    for (int i = 2; i <= n; ++i) {
        if (!is_comp[i]) primes.push_back(i);
        for (int p : primes) {
            if ((int64)i * p > n) break;
            is_comp[i * p] = true;
            if (i % p == 0) break;
        }
    }
    return primes.size();
}
int64 mod_pow_ll(int64 a, int64 b, int64 mod) {
    int64 r = 1;
    while (b) {
        if (b & 1) r = (__int128)r * a % mod;
        a = (__int128)a * a % mod;
        b >>= 1;
    }
    return r;
}
// C(n,k) % mod，mod 为质数且 n,k < mod
int64 comb_mod(int n, int k, int64 mod) {
    if (k < 0 || k > n) return 0;
    vector<int64> fact(n + 1, 1), inv_fact(n + 1, 1);
    for (int i = 1; i <= n; ++i) fact[i] = (__int128)fact[i - 1] * i % mod;
    inv_fact[n] = mod_pow_ll(fact[n], mod - 2, mod);
    for (int i = n; i > 0; --i) inv_fact[i - 1] = (__int128)inv_fact[i] * i % mod;
    return (__int128)fact[n] * inv_fact[k] % mod * inv_fact[n - k] % mod;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    if (!(cin >> n >> q)) return 0;
    cout << sieve_count(n) << '\n';
    for (int i = 0; i < q; ++i) {
        int nn, kk; int64 p;
        cin >> nn >> kk >> p;
        cout << comb_mod(nn, kk, p) << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
// 除一个数外其余都出现两次，异或找出那个数
int64 single_number(const vector<int64> &a) {
    int64 x = 0;
    for (int64 v : a) x ^= v;
    return x;
}
// 二进制中 1 的个数
int popcount_ll(int64 x) {
    int c = 0;
    while (x) { x &= x - 1; ++c; }
    return c;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<int64> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    int64 s = single_number(a);
    cout << s << '\n' << popcount_ll(s >= 0 ? s : -s) << '\n';
    return 0;
}

template_python:
class Fenwick:
    '''树状数组：单点加、区间和查询，1-based。'''

    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, v):
        while i <= self.n:
            self.bit[i] += v
            i += i & -i

    def prefix(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s

    def range_sum(self, l, r):
        return self.prefix(r) - self.prefix(l - 1)


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n, q = data[0], data[1]
    a = data[2:2 + n]
    fw = Fenwick(n)
    for i, v in enumerate(a, 1):
        fw.add(i, v)
    pos = 2 + n
    out = []
    for _ in range(q):
        op = data[pos]
        if op == 1:
            fw.add(data[pos + 1], data[pos + 2])
            pos += 3
        else:
            out.append(str(fw.range_sum(data[pos + 1], data[pos + 2])))
            pos += 3
    sys.stdout.write('\n'.join(out))

