    bool first = true;
    auto out = [&](int v) {
        if (!first) cout << ' ';
        first = false;
        cout << v;
    };
    while (up <= down && left <= right) {
        for (int c = left; c <= right; ++c) out(a[up * m + c]);
        ++up;
        for (int r = up; r <= down; ++r) out(a[r * m + right]);
        --right;
        if (up <= down) {
            for (int c = right; c >= left; --c) out(a[down * m + c]);
            --down;
        }
        if (left <= right) {
            for (int r = down; r >= up; --r) out(a[r * m + left]);
            ++left;
        }
    }
    cout << '\n';
    return 0;
}

