def solve():
    import sys
    s = sys.stdin.read().strip()
    n = len(s)
    best = ""
    for c in range(n):
        l = r = c  # 奇回文：中心是 s[c]
        while l >= 0 and r < n and s[l] == s[r]:
            if r - l + 1 > len(best):
                best = s[l:r + 1]
            l -= 1
            r += 1
        l, r = c, c + 1  # 偶回文：中心是 s[c] 与 s[c+1] 之间
        while l >= 0 and r < n and s[l] == s[r]:
            if r - l + 1 > len(best):
                best = s[l:r + 1]
            l -= 1
            r += 1
    sys.stdout.write(best)


if __name__ == "__main__":
