#include <bits/stdc++.h>
using namespace std;
struct ListNode {
    int val;
    ListNode *next;
    ListNode(int v = 0, ListNode *n = nullptr): val(v), next(n) {}
};
ListNode* build(const vector<int> &a) {
    ListNode dummy;
    ListNode *cur = &dummy;
    for (int v: a) { cur->next = new ListNode(v); cur = cur->next;}
    return dummy.next;
}
// 哨兵节点合并两条有序链表
ListNode* merge_two(ListNode *l1, ListNode *l2) {
    ListNode dummy;
    ListNode *cur = &dummy;
    while (l1 && l2) {
        if (l1->val <= l2->val) { cur->next = l1; l1 = l1->next;}
        else { cur->next = l2; l2 = l2->next;}
        cur = cur->next;
    }
    cur->next = l1 ? l1 : l2;
    return dummy.next;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    int m; cin >> m;
    vector<int> b(m);
    for (int i = 0; i < m; ++i) cin >> b[i];
    ListNode *head = merge_two(build(a), build(b));
    bool first = true;
    for (ListNode *p = head; p; p = p->next) {
        if (!first) cout << ' ';
        cout << p->val;
        first = false;
    }
    cout << '\n';
    return 0;
}

template_python:
class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    dummy = cur = ListNode()
    for v in vals:
        cur.next = ListNode(v)
        cur = cur.next
    return dummy.next


def to_list(head):
    res = []
    while head:
        res.append(head.val)
        head = head.next
    return res


def merge_two(l1, l2):
    '''哨兵节点合并两条有序链表。'''
    dummy = cur = ListNode()
    while l1 and l2:
        if l1.val <= l2.val:
            cur.next, l1 = l1, l1.next
        else:
            cur.next, l2 = l2, l2.next
        cur = cur.next
    cur.next = l1 or l2
    return dummy.next


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n = data[0]
    a = data[1:1 + n]
    m = data[1 + n]
    b = data[2 + n:2 + n + m]
    print(' '.join(map(str, to_list(merge_two(build(a), build(b))))))

