#include <bits/stdc++.h>
using namespace std;
// a 是层序数组（-1 表示空），返回层序遍历值
vector<int> level_order(const vector<int> &a) {
    vector<int> res;
    if (a.empty() || a[0] == -1) return res;
    queue<int> q;
    q.push(0);
    while (!q.empty()) {
        int i = q.front(); q.pop();
        if (a[i] == -1) continue;
        res.push_back(a[i]);
        int left = 2 * i + 1, right = 2 * i + 2;
        if (left < (int)a.size()) q.push(left);
        if (right < (int)a.size()) q.push(right);
    }
    return res;
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    auto r = level_order(a);
    for (int i = 0; i < (int)r.size(); ++i)
    cout << r[i] << (i + 1 == (int)r.size() ? '\n' : ' ');
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
// a 是层序数组（-1 表示空），判断是否为二叉搜索树（严格左<根<右）
bool dfs(const vector<int> &a, int i, long long lo, long long hi) {
    if (i >= (int)a.size() || a[i] == -1) return true;
    long long v = a[i];
    if (v <= lo || v >= hi) return false;
    return dfs(a, 2 * i + 1, lo, v) && dfs(a, 2 * i + 2, v, hi);
}
bool is_bst(const vector<int> &a) {
    if (a.empty() || a[0] == -1) return true;
    return dfs(a, 0, LLONG_MIN, LLONG_MAX);
}
