def gen_parentheses(n):
    """生成 n 对括号的全部合法组合，'(' 优先即字典序。"""
    res = []

    def dfs(s, open_, close):
        if len(s) == 2 * n:
            res.append(s)
            return
        if open_ < n:
            dfs(s + '(', open_ + 1, close)
        if close < open_:
            dfs(s + ')', open_, close + 1)

    dfs('', 0, 0)
    return res


