def bounded_knapsack(items, W):
    '''items 是 (重量, 价值, 件数) 列表；二进制拆分转 01 背包。'''
    objs = []
    for w, v, k in items:
        t = 1
        while k > 0:
            c = t if t < k else k
            objs.append((w * c, v * c))
            k -= c
            t <<= 1
    dp = [0] * (W + 1)
    for w, v in objs:          # 01 背包：容量倒序
        for j in range(W, w - 1, -1):
            if dp[j - w] + v > dp[j]:
                dp[j] = dp[j - w] + v
    return max(dp)


