using namespace std;
using int64 = long long;
// 归并排序求逆序对数，返回 {排好序的数组, 逆序对数}
pair<vector<int64>, int64> sort_count(vector<int64> a) {
    int64 n = (int64)a.size();
    if (n <= 1) return {a, 0};
    int64 mid = n / 2;
    vector<int64> left(a.begin(), a.begin() + mid);
    vector<int64> right(a.begin() + mid, a.end());
    auto pl = sort_count(move(left));
    auto pr = sort_count(move(right));
    vector<int64> &sl = pl.first, &sr = pr.first;
    vector<int64> merged;
    merged.reserve(n);
    int64 i = 0, j = 0, c = pl.second + pr.second;
    while (i < (int64)sl.size() && j < (int64)sr.size()) {
        if (sl[i] <= sr[j]) merged.push_back(sl[i++]);
        else {
            merged.push_back(sr[j++]);
            c += (int64)sl.size() - i;  // 左半剩余的都比它大
        }
    }
    while (i < (int64)sl.size()) merged.push_back(sl[i++]);
    while (j < (int64)sr.size()) merged.push_back(sr[j++]);
    return {merged, c};
}
