    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<int64> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    cout << sort_count(a).second << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
// 单点加、区间求和。下标 0-based，查询区间 [l, r)
struct SegTree {
    int n;
    vector<int64> t;
    SegTree(const vector<int64> &a = {}) { init(a); }
    void init(const vector<int64> &a) {
        int sz = (int)a.size();
        n = 1;
        while (n < sz) n <<= 1;
        t.assign(2 * n, 0);
        for (int i = 0; i < sz; ++i) t[n + i] = a[i];
        for (int i = n - 1; i > 0; --i) t[i] = t[i << 1] + t[i << 1 | 1];
    }
    void add(int pos, int64 delta) {
        int i = n + pos;
        t[i] += delta;
        for (i >>= 1; i; i >>= 1) t[i] = t[i << 1] + t[i << 1 | 1];
    }
    int64 query(int l, int r) {  // [l, r)
        int64 res = 0;
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) res += t[l++];
            if (r & 1) res += t[--r];
        }
        return res;
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    if (!(cin >> n >> q)) return 0;
    vector<int64> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    SegTree st(a);
    for (int k = 0; k < q; ++k) {
        int typ;
        cin >> typ;
        if (typ == 1) {          // 单点加：1 i x 表示 a[i] += x（1-based）
            int i;
            int64 x;
            cin >> i >> x;
            st.add(i - 1, x);
        } else {                 // 区间求和：2 l r（1-based 闭区间）
            int l, r;
            cin >> l >> r;
            cout << st.query(l - 1, r) << '\n';
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
// 静态区间最大值：O(n log n) 预处理，O(1) 查询
struct SparseTable {
    int n, LOG;
    vector<vector<int>> st;
    vector<int> lg;
    SparseTable(const vector<int> &a = {}) { init(a); }
    void init(const vector<int> &a) {
        n = (int)a.size();
        LOG = 1;
        while ((1 << LOG) <= n) ++LOG;
        st.assign(LOG, vector<int>(n));
        st[0] = a;
        for (int k = 1; k < LOG; ++k)
            for (int i = 0; i + (1 << k) <= n; ++i)
                st[k][i] = max(st[k - 1][i], st[k - 1][i + (1 << (k - 1))]);
        lg.assign(n + 1, 0);
        for (int i = 2; i <= n; ++i) lg[i] = lg[i >> 1] + 1;
    }
    int query(int l, int r) const {  // [l, r) 0-based
        int k = lg[r - l];
        return max(st[k][l], st[k][r - (1 << k)]);
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    if (!(cin >> n >> q)) return 0;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    SparseTable sp(a);
    for (int k = 0; k < q; ++k) {
        int l, r;  // 1-based 闭区间
        cin >> l >> r;
        cout << sp.query(l - 1, r) << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const long long MOD1 = 1000000007LL;
const long long MOD2 = 1000000009LL;
const long long BASE = 131;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    if (!(cin >> s)) return 0;
    int n = (int)s.size();
    vector<long long> h1(n + 1, 0), h2(n + 1, 0), p1(n + 1, 1), p2(n + 1, 1);
    for (int i = 0; i < n; ++i) {
        long long code = (unsigned char)s[i];
        h1[i + 1] = (h1[i] * BASE + code) % MOD1;
        h2[i + 1] = (h2[i] * BASE + code) % MOD2;
        p1[i + 1] = (p1[i] * BASE) % MOD1;
        p2[i + 1] = (p2[i] * BASE) % MOD2;
    }
    // 取 s[l:r)（0-based，左闭右开）的双哈希
    auto get = [&](int l, int r) {
        long long x1 = (h1[r] - h1[l] * p1[r - l]) % MOD1;
        long long x2 = (h2[r] - h2[l] * p2[r - l]) % MOD2;
        if (x1 < 0) x1 += MOD1;
        if (x2 < 0) x2 += MOD2;
        return pair<long long, long long>(x1, x2);
    };
    int q;
    cin >> q;
    while (q--) {
        int l1, r1, l2, r2;
        cin >> l1 >> r1 >> l2 >> r2;
        --l1;
        --l2;
        cout << (get(l1, r1) == get(l2, r2) ? "YES" : "NO") << '\n';
    }
    return 0;
}

