import sys
from collections import deque


class ACAutomaton:
    """多模式串匹配。只支持小写字母。"""

    def __init__(self):
        self.next = [[-1] * 26]
        self.fail = [0]
        self.out = [[]]
        self.order = []      # BFS 序，用于出现次数的反向累加
        self.pat_node = []   # pid -> 终止节点

    def add(self, word, pid):
        node = 0
        for ch in word:
            c = ord(ch) - 97
            if self.next[node][c] == -1:
                self.next[node][c] = len(self.next)
                self.next.append([-1] * 26)
                self.fail.append(0)
                self.out.append([])
            node = self.next[node][c]
        self.out[node].append(pid)
        while len(self.pat_node) <= pid:
            self.pat_node.append(0)
        self.pat_node[pid] = node

    def build(self):
        q = deque()
        for c in range(26):
            v = self.next[0][c]
            if v != -1:
                self.fail[v] = 0
                q.append(v)
                self.order.append(v)
            else:
                self.next[0][c] = 0
        while q:
            u = q.popleft()
            for c in range(26):
                v = self.next[u][c]
                if v != -1:
                    self.fail[v] = self.next[self.fail[u]][c]
                    q.append(v)
                    self.order.append(v)
                else:
                    self.next[u][c] = self.next[self.fail[u]][c]

    def count_each(self, text, m):
        """返回每个模式串在 text 中的出现次数（含重叠）。"""
        cnt = [0] * len(self.next)
        node = 0
        for ch in text:
            node = self.next[node][ord(ch) - 97]
            cnt[node] += 1
        for u in reversed(self.order):
            cnt[self.fail[u]] += cnt[u]
        ans = [0] * m
        for pid in range(m):
            ans[pid] = cnt[self.pat_node[pid]]
        return ans


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    pats = data[1:1 + n]
    text = data[1 + n]
    ac = ACAutomaton()
    for i, p in enumerate(pats):
        ac.add(p, i)
    ac.build()
    print("\n".join(map(str, ac.count_each(text, n))))


if __name__ == "__main__":
    main()

template_cpp:
#include <bits/stdc++.h>
using namespace std;

struct ACAutomaton {
    // 只支持小写字母
    vector<array<int, 26>> next;
    vector<int> fail;
    vector<vector<int>> out;
    vector<int> order;     // BFS 序，用于出现次数的反向累加
    vector<int> pat_node;  // pid -> 终止节点

    ACAutomaton() {
        next.push_back({});
        next[0].fill(-1);
        fail.push_back(0);
        out.emplace_back();
    }

    void add(const string &word, int pid) {
        int node = 0;
        for (char ch : word) {
            int c = ch - 'a';
            if (next[node][c] == -1) {
                next[node][c] = (int)next.size();
                next.push_back({});
                next.back().fill(-1);
                fail.push_back(0);
                out.emplace_back();
            }
            node = next[node][c];
        }
        out[node].push_back(pid);
        if ((int)pat_node.size() <= pid) pat_node.resize(pid + 1);
        pat_node[pid] = node;
    }

    void build() {
        queue<int> q;
        for (int c = 0; c < 26; ++c) {
            int v = next[0][c];
            if (v != -1) {
                fail[v] = 0;
                q.push(v);
                order.push_back(v);
            } else {
                next[0][c] = 0;
            }
        }
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int c = 0; c < 26; ++c) {
                int v = next[u][c];
                if (v != -1) {
                    fail[v] = next[fail[u]][c];
                    q.push(v);
                    order.push_back(v);
                } else {
                    next[u][c] = next[fail[u]][c];
                }
            }
        }
    }

    // 返回每个模式串在 text 中的出现次数（含重叠）
    vector<long long> count_each(const string &text, int m) {
        vector<long long> cnt(next.size(), 0);
        int node = 0;
        for (char ch : text) {
            node = next[node][ch - 'a'];
            cnt[node] += 1;
        }
        for (int i = (int)order.size() - 1; i >= 0; --i) {
            int u = order[i];
            cnt[fail[u]] += cnt[u];
        }
        vector<long long> ans(m, 0);
        for (int pid = 0; pid < m; ++pid) ans[pid] = cnt[pat_node[pid]];
        return ans;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<string> pats(n);
    for (int i = 0; i < n; ++i) cin >> pats[i];
    string text;
    cin >> text;
    ACAutomaton ac;
    for (int i = 0; i < n; ++i) ac.add(pats[i], i);
    ac.build();
    auto ans = ac.count_each(text, n);
    for (int i = 0; i < n; ++i) cout << ans[i] << '\n';
    return 0;
}

