struct XorTrie {
    int bits;
    vector<array<int, 2>> child;
    XorTrie(int b = 30) : bits(b) {
        child.push_back({-1, -1});
    }
    void insert(int x) {
        int node = 0;
        for (int b = bits; b >= 0; --b) {
            int bit = (x >> b) & 1;
            if (child[node][bit] == -1) {
                child[node][bit] = (int)child.size();
                child.push_back({-1, -1});
            }
            node = child[node][bit];
        }
