        int res = 0;
        for (int b = bits; b >= 0; --b) {
            int bit = (x >> b) & 1;
            int want = bit ^ 1;
            if (child[node][want] != -1) {
                res |= (1 << b);
                node = child[node][want];
            } else {
                node = child[node][bit];
            }
        }
        return res;
    }
};

