import sys


def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    q = int(next(it))
    a = [0] * (n + 1)
    for i in range(1, n + 1):
        a[i] = int(next(it))
    tree = [0] * (4 * n + 5)
    lazy = [0] * (4 * n + 5)

    def build(node, l, r):
        if l == r:
            tree[node] = a[l]
            return
        mid = (l + r) // 2
        build(node * 2, l, mid)
        build(node * 2 + 1, mid + 1, r)
        tree[node] = tree[node * 2] + tree[node * 2 + 1]

    def push(node, l, r):
        if lazy[node] != 0 and l != r:
            mid = (l + r) // 2
            for child, cl, cr in ((node * 2, l, mid), (node * 2 + 1, mid + 1, r)):
                tree[child] += lazy[node] * (cr - cl + 1)
                lazy[child] += lazy[node]
            lazy[node] = 0

    def seg_add(node, l, r, ql, qr, val):
        if ql <= l and r <= qr:
            tree[node] += val * (r - l + 1)
            lazy[node] += val
            return
        push(node, l, r)
        mid = (l + r) // 2
        if ql <= mid:
            seg_add(node * 2, l, mid, ql, qr, val)
        if qr > mid:
            seg_add(node * 2 + 1, mid + 1, r, ql, qr, val)
        tree[node] = tree[node * 2] + tree[node * 2 + 1]

    def seg_sum(node, l, r, ql, qr):
        if ql <= l and r <= qr:
            return tree[node]
        push(node, l, r)
        mid = (l + r) // 2
        res = 0
        if ql <= mid:
            res += seg_sum(node * 2, l, mid, ql, qr)
        if qr > mid:
            res += seg_sum(node * 2 + 1, mid + 1, r, ql, qr)
        return res

    build(1, 1, n)
    out = []
    for _ in range(q):
        t = int(next(it))
        l = int(next(it))
        r = int(next(it))
        if t == 1:
            x = int(next(it))
            seg_add(1, 1, n, l, r, x)
        else:
            out.append(str(seg_sum(1, 1, n, l, r)))
    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    sys.setrecursionlimit(1 << 25)
    solve()

