void range_add(int l, int r, long long v) {
    int bl = (l - 1) / B;
    int br = (r - 1) / B;
    if (bl == br) {
        for (int i = l; i <= r; i++) {
            a[i] += v;
            block_sum[bl] += v;
        }
        return;
    }
    int end_l = (bl + 1) * B;
    for (int i = l; i <= end_l; i++) {
        a[i] += v;
        block_sum[bl] += v;
    }
    for (int b = bl + 1; b < br; b++) {
        block_add[b] += v;
        block_sum[b] += v * B;
    }
    int start_r = br * B + 1;
    for (int i = start_r; i <= r; i++) {
        a[i] += v;
        block_sum[br] += v;
    }
}

long long range_sum(int l, int r) {
    int bl = (l - 1) / B;
    int br = (r - 1) / B;
    long long res = 0;
    if (bl == br) {
        for (int i = l; i <= r; i++) {
            res += a[i] + block_add[bl];
        }
        return res;
    }
    int end_l = (bl + 1) * B;
    for (int i = l; i <= end_l; i++) {
        res += a[i] + block_add[bl];
    }
    for (int b = bl + 1; b < br; b++) {
        res += block_sum[b];
    }
    int start_r = br * B + 1;
    for (int i = start_r; i <= r; i++) {
        res += a[i] + block_add[br];
    }
    return res;
}

