const int MAXN = 200005;

int parent_[MAXN];
long long dist_[MAXN];  // x 到它所在集合根的距离

int find_root(int x) {
    if (parent_[x] == x) {
        return x;
    }
    int p = parent_[x];
    int r = find_root(p);
    dist_[x] += dist_[p];
    parent_[x] = r;
    return r;
}

