#include <bits/stdc++.h>
using namespace std;

int n, m;
vector<vector<long long>> bit;

void add(int x, int y, long long v) {
    for (int i = x; i <= n; i += i & -i) {
        for (int j = y; j <= m; j += j & -j) {
            bit[i][j] += v;
        }
    }
}

long long prefix_sum(int x, int y) {
    long long res = 0;
    for (int i = x; i > 0; i -= i & -i) {
        for (int j = y; j > 0; j -= j & -j) {
            res += bit[i][j];
        }
    }
    return res;
}

