            cin >> x >> y >> v;
            add(x, y, v);
        } else {
            int x1, y1, x2, y2;
            cin >> x1 >> y1 >> x2 >> y2;
            long long ans = prefix_sum(x2, y2) - prefix_sum(x1 - 1, y2)
            - prefix_sum(x2, y1 - 1) + prefix_sum(x1 - 1, y1 - 1);
            cout << ans << '\n';
        }
    }
    return 0;
}

