#include <bits/stdc++.h>
using namespace std;

struct Node {
    int val;
    Node *l = nullptr, *r = nullptr;
};

Node* build(const vector<int> &level) {
    if (level.empty()) return nullptr;
    vector<Node*> nodes;
    for (int v : level) {
        nodes.push_back(v == -1 ? nullptr : new Node{v});
    }
    for (size_t i = 0; i < nodes.size(); ++i) {
        if (!nodes[i]) continue;
        size_t l = 2 * i + 1, r = 2 * i + 2;
        if (l < nodes.size()) nodes[i]->l = nodes[l];
        if (r < nodes.size()) nodes[i]->r = nodes[r];
    }
    return nodes[0];
}

// 层序序列化：空节点记 #，末尾多余的 # 去掉
string serialize(Node *root) {
    if (!root) return "";
    vector<string> out;
    queue<Node*> q;
    q.push(root);
    while (!q.empty()) {
        Node *nd = q.front(); q.pop();
        if (!nd) { out.push_back("#"); continue; }
        out.push_back(to_string(nd->val));
        q.push(nd->l);
        q.push(nd->r);
    }
    while (!out.empty() && out.back() == "#") out.pop_back();
    string s;
    for (size_t i = 0; i < out.size(); ++i) {
        if (i) s += ',';
        s += out[i];
    }
    return s;
}

// 把 serialize 的格式还原成树
Node* deserialize(const string &s) {
    if (s.empty()) return nullptr;
    vector<string> vals;
    string cur;
    for (char c : s) {
        if (c == ',') { vals.push_back(cur); cur.clear(); }
        else cur.push_back(c);
    }
    vals.push_back(cur);
    Node *root = new Node{stoi(vals[0])};
    queue<Node*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < vals.size()) {
        Node *nd = q.front(); q.pop();
        for (int side = 0; side < 2; ++side) {
            if (i < vals.size() && vals[i] != "#") {
                Node *ch = new Node{stoi(vals[i])};
                if (side == 0) nd->l = ch; else nd->r = ch;
                q.push(ch);
            }
            ++i;
        }
    }
    return root;
}

void preorder(Node *nd, vector<string> &res) {
    if (!nd) return;
    res.push_back(to_string(nd->val));
    preorder(nd->l, res);
    preorder(nd->r, res);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    // 输入：层序数组，-1 表空；输出：序列化→反序列化后先序序列
    vector<int> level;
    int v;
    while (cin >> v) level.push_back(v);
    Node *back = deserialize(serialize(build(level)));
    vector<string> res;
    preorder(back, res);
    for (size_t i = 0; i < res.size(); ++i) {
        if (i) cout << ' ';
        cout << res[i];
    }
    cout << '\n';
    return 0;
}

