using namespace std;
using int64 = long long;

int n;
vector<vector<pair<int,int64>>> g;
vector<int64> sub_, sz_, ans_;

void dfs1(int u, int p) {
    sz_[u] = 1;
    sub_[u] = 0;
    for (auto [v, w] : g[u]) {
        if (v == p) continue;
        dfs1(v, u);
        sz_[u] += sz_[v];
        sub_[u] += sub_[v] + sz_[v] * w;
    }
}

void dfs2(int u, int p) {
    for (auto [v, w] : g[u]) {
        if (v == p) continue;
        // 根从 u 换到 v：v 子树内 sz[v] 个点距离 -w，其余 n - sz[v] 个点 +w
        ans_[v] = ans_[u] + (n - 2 * sz_[v]) * w;
        dfs2(v, u);
    }
}

