import sys

sys.setrecursionlimit(10 ** 6)


def solve() -> None:
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return
    n, m, k = data[0], data[1], data[2]
    g = [[] for _ in range(n + 1)]
    idx = 3
    for _ in range(k):
        u, v = data[idx], data[idx + 1]
        idx += 2
        g[u].append(v)
    match_r = [0] * (m + 1)  # 右部点 v 当前匹配的左部点

    def bpm(u, vis):
        for v in g[u]:
            if vis[v]:
                continue
            vis[v] = True
            if match_r[v] == 0 or bpm(match_r[v], vis):
                match_r[v] = u
                return True
        return False

    ans = 0
    for u in range(1, n + 1):
        vis = [False] * (m + 1)
        if bpm(u, vis):
            ans += 1
    print(ans)


if __name__ == '__main__':
    # 输入：左部点数 n，右部点数 m，边数 k；接下来 k 行 u v；输出：最大匹配数
    solve()

