    vector<vector<pair<int,int>>> adj(n + 1);
    for (int i = 0; i < m; ++i) {
        int x, y, c;
        cin >> x >> y >> c;
        adj[y].push_back({x, c});
    }
    for (int v = 1; v <= n; ++v) adj[0].push_back({v, 0});  // 超级源点
    vector<long long> dist(n + 1, 0);
    vector<char> inq(n + 1, 1);
    vector<int> cnt(n + 1, 0);
    queue<int> q;
    for (int v = 0; v <= n; ++v) q.push(v);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = 0;
        for (auto [v, w] : adj[u]) {
            if (dist[v] > dist[u] + w) {
                dist[v] = dist[u] + w;
                if (!inq[v]) {
                    inq[v] = 1;
                    q.push(v);
                    if (++cnt[v] > n + 1) {  // 入队太多次 → 负环 → 无解
                        cout << "No Solution\n";
                        return 0;
                    }
                }
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        if (i > 1) cout << ' ';
        cout << dist[i];
    }
    cout << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int N, timer_ = 0, comp_id_ = 0;
vector<vector<int>> g;
vector<int> disc_, low_, comp_;
vector<char> on_stack_;
vector<int> st_;

void dfs(int u) {
    disc_[u] = low_[u] = ++timer_;
    st_.push_back(u);
    on_stack_[u] = 1;
    for (int v : g[u]) {
        if (disc_[v] == 0) {
            dfs(v);
            low_[u] = min(low_[u], low_[v]);
        } else if (on_stack_[v]) {
            low_[u] = min(low_[u], disc_[v]);
        }
    }
    if (low_[u] == disc_[u]) {
        while (true) {
            int x = st_.back(); st_.pop_back();
            on_stack_[x] = 0;
            comp_[x] = comp_id_;
            if (x == u) break;
        }
        ++comp_id_;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    // 输入：n m，接下来 m 行 a b 表示子句 (a OR b)，正数 k 表 xk 为真，负数 -k 表 xk 为假
    int n, m;
    if (!(cin >> n >> m)) return 0;
    // 变量 i(1-based)：假文字 2*(i-1)，真文字 2*(i-1)+1；取反 = xor 1
    N = 2 * n;
    g.assign(N, {});
    auto lit = [&](int x) { return 2 * (abs(x) - 1) + (x > 0 ? 1 : 0); };
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        int la = lit(a), lb = lit(b);
        g[la ^ 1].push_back(lb);  // !a -> b
        g[lb ^ 1].push_back(la);  // !b -> a
    }
    disc_.assign(N, 0);
    low_.assign(N, 0);
    comp_.assign(N, -1);
    on_stack_.assign(N, 0);
    for (int u = 0; u < N; ++u) {
        if (disc_[u] == 0) dfs(u);
    }
    vector<int> val(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        int f = 2 * (i - 1), t = 2 * (i - 1) + 1;
        if (comp_[f] == comp_[t]) {
            cout << "IMPOSSIBLE\n";
            return 0;
        }
        // Tarjan 按逆拓扑顺序给分量编号：假文字的分量编号更大 → 该变量取真
        val[i] = (comp_[f] > comp_[t]) ? 1 : 0;
    }
    cout << "POSSIBLE\n";
    for (int i = 1; i <= n; ++i) {
        if (i > 1) cout << ' ';
        cout << val[i];
    }
    cout << '\n';
    return 0;
}

