def max_flow(n, s, t, edges):
    '''Dinic 最大流。edges 为 (u, v, c) 列表，节点编号 1..n。'''
    from collections import deque
    g = [[] for _ in range(n + 1)]

    def add_edge(u, v, c):
        g[u].append([v, c, len(g[v])])
        g[v].append([u, 0, len(g[u]) - 1])

    for u, v, c in edges:
        add_edge(u, v, c)

    flow = 0
    INF = 10 ** 18
    while True:
        level = [-1] * (n + 1)
        level[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for v, c, _ in g[u]:
                if c > 0 and level[v] < 0:
                    level[v] = level[u] + 1
                    q.append(v)
        if level[t] < 0:
            break
        it = [0] * (n + 1)

        def dfs(u, f):
            if u == t:
                return f
            while it[u] < len(g[u]):
                v, c, rev = g[u][it[u]]
                if c > 0 and level[v] == level[u] + 1:
                    ret = dfs(v, min(f, c))
                    if ret > 0:
                        g[u][it[u]][1] -= ret
                        g[v][rev][1] += ret
                        return ret
                it[u] += 1
            return 0

        while True:
            pushed = dfs(s, INF)
            if pushed == 0:
                break
            flow += pushed
    return flow


