template_cpp:
#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int64 INF64 = (int64)4e18;

struct Dinic {
    struct Edge { int to; int64 cap; int rev; };
    int n;
    vector<vector<Edge>> g;
    vector<int> level, it;
    Dinic(int n = 0) { init(n); }
    void init(int n_) { n = n_; g.assign(n + 1, {}); }
    void add_edge(int u, int v, int64 c) {
        Edge a{v, c, (int)g[v].size()};
        Edge b{u, 0, (int)g[u].size()};
        g[u].push_back(a);
        g[v].push_back(b);
    }
    bool bfs(int s, int t) {
        level.assign(n + 1, -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto &e : g[u]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] >= 0;
    }
    int64 dfs(int u, int t, int64 f) {
        if (u == t) return f;
        for (int &i = it[u]; i < (int)g[u].size(); ++i) {
            Edge &e = g[u][i];
            if (e.cap > 0 && level[e.to] == level[u] + 1) {
                int64 ret = dfs(e.to, t, min(f, e.cap));
                if (ret > 0) {
                    e.cap -= ret;
                    g[e.to][e.rev].cap += ret;
                    return ret;
                }
            }
        }
        return 0;
    }
    int64 max_flow(int s, int t) {
        int64 flow = 0;
        while (bfs(s, t)) {
            it.assign(n + 1, 0);
            while (true) {
                int64 pushed = dfs(s, t, INF64);
                if (pushed == 0) break;
                flow += pushed;
            }
        }
        return flow;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, s, t;
    if (!(cin >> n >> m >> s >> t)) return 0;
    Dinic dinic(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        int64 c;
        cin >> u >> v >> c;
        dinic.add_edge(u, v, c);
    }
    cout << dinic.max_flow(s, t) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int64 INF64 = (int64)4e18;

struct MinCostFlow {
    struct Edge { int to; int64 cap, cost; int rev; };
    int n;
    vector<vector<Edge>> g;
    MinCostFlow(int n = 0) { init(n); }
    void init(int n_) { n = n_; g.assign(n + 1, {}); }
    void add_edge(int u, int v, int64 cap, int64 cost) {
        Edge a{v, cap, cost, (int)g[v].size()};
        Edge b{u, 0, -cost, (int)g[u].size()};
        g[u].push_back(a);
        g[v].push_back(b);
    }
    // 返回 {流量, 费用}
    pair<int64, int64> min_cost_flow(int s, int t) {
        int64 flow = 0, cost = 0;
        vector<int64> pot(n + 1, 0), dist(n + 1);
        vector<int> pre_v(n + 1), pre_e(n + 1);
        while (true) {
            fill(dist.begin(), dist.end(), INF64);
            dist[s] = 0;
            using P = pair<int64, int>;
            priority_queue<P, vector<P>, greater<P>> pq;
            pq.emplace(0, s);
            while (!pq.empty()) {
                auto [d, u] = pq.top(); pq.pop();
                if (d != dist[u]) continue;
                for (int i = 0; i < (int)g[u].size(); ++i) {
                    Edge &e = g[u][i];
                    if (e.cap > 0) {
                        int64 nd = d + e.cost + pot[u] - pot[e.to];
                        if (nd < dist[e.to]) {
                            dist[e.to] = nd;
                            pre_v[e.to] = u;
                            pre_e[e.to] = i;
                            pq.emplace(nd, e.to);
                        }
                    }
                }
            }
            if (dist[t] == INF64) break;
            for (int i = 1; i <= n; ++i) {
                if (dist[i] < INF64) pot[i] += dist[i];
            }
            int64 add = INF64;
            for (int v = t; v != s; v = pre_v[v]) {
                add = min(add, g[pre_v[v]][pre_e[v]].cap);
            }
            for (int v = t; v != s; v = pre_v[v]) {
                Edge &e = g[pre_v[v]][pre_e[v]];
                e.cap -= add;
                g[v][e.rev].cap += add;
                cost += add * e.cost;
            }
            flow += add;
        }
        return {flow, cost};
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, s, t;
    if (!(cin >> n >> m >> s >> t)) return 0;
    MinCostFlow mcf(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        int64 cap, cost;
        cin >> u >> v >> cap >> cost;
        mcf.add_edge(u, v, cap, cost);
    }
    auto [flow, cost] = mcf.min_cost_flow(s, t);
    cout << flow << ' ' << cost << '\n';
    return 0;
}

template_python:
def layered_dijkstra(n, edges, k, s, t):
    '''分层图最短路：edges 为 (u, v, w) 无向边，最多 k 条边可以免费走。'''
    import heapq
    g = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        g[u].append((v, w))
        g[v].append((u, w))
    INF = 10 ** 18
    dist = [[INF] * (k + 1) for _ in range(n + 1)]
    dist[s][0] = 0
    pq = [(0, s, 0)]
    while pq:
        d, u, used = heapq.heappop(pq)
        if d != dist[u][used]:
            continue
        for v, w in g[u]:
            if dist[v][used] > d + w:
                dist[v][used] = d + w
                heapq.heappush(pq, (d + w, v, used))
            if used < k and dist[v][used + 1] > d:
                dist[v][used + 1] = d
                heapq.heappush(pq, (d, v, used + 1))
    return min(dist[t])


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n, m, k, s, t = data[:5]
    edges = [(data[5 + 3 * i], data[6 + 3 * i], data[7 + 3 * i]) for i in range(m)]
    print(layered_dijkstra(n, edges, k, s, t))

