def kth_ancestor(n, parent, queries):
    '''倍增求 k 级祖先。parent[2..n] 为父节点（parent[1] = 0），queries 为 (u, k) 列表。'''
    LOG = n.bit_length()
    up = [[0] * (n + 1) for _ in range(LOG)]
    for i in range(2, n + 1):
        up[0][i] = parent[i]
    for j in range(1, LOG):
        uj, ujm = up[j], up[j - 1]
        for i in range(1, n + 1):
            anc = ujm[i]
            uj[i] = ujm[anc] if anc else 0
    res = []
    for u, k in queries:
        bit = 0
        while k and u:
            if k & 1:
                u = up[bit][u]
            k >>= 1
            bit += 1
        res.append(u)
    return res


if __name__ == '__main__':
