using Matrix = vector<vector<int64>>;

Matrix mat_mul(const Matrix &a, const Matrix &b, int64 mod) {
    int n = (int)a.size();
    Matrix c(n, vector<int64>(n, 0));
    for (int i = 0; i < n; i++) {
        for (int k = 0; k < n; k++) {
            int64 aik = a[i][k];
            if (aik == 0) {
                continue;  // 跳过 0，稀疏矩阵能快不少
            }
            for (int j = 0; j < n; j++) {
                // aik, b[k][j] < mod，乘积 < 1e18，long long 够用
                c[i][j] = (c[i][j] + aik * b[k][j]) % mod;
            }
        }
    }
    return c;
}

Matrix mat_pow(Matrix base, int64 power, int64 mod) {
    int n = (int)base.size();
    Matrix res(n, vector<int64>(n, 0));
    for (int i = 0; i < n; i++) {
        res[i][i] = 1 % mod;  // 单位矩阵
    }
    while (power > 0) {
        if (power & 1) {
            res = mat_mul(res, base, mod);
        }
        base = mat_mul(base, base, mod);
        power >>= 1;
    }
    return res;
}

