        return x < o.x || (x == o.x && y < o.y);
    }
    bool operator==(const Pt &o) const { return x == o.x && y == o.y; }
};

long long cross(const Pt &o, const Pt &a, const Pt &b) {
    return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
