    r = 0
    for qi in order:
        l, qr = queries[qi]
        while r < qr:
            r += 1
            v = a[r - 1]
            if v in last:
                bit.add(last[v], -1)
            bit.add(r, 1)
            last[v] = r
        ans[qi] = bit.sum(qr) - bit.sum(l - 1)
    return ans


if __name__ == '__main__':
    data = list(map(int, sys.stdin.read().split()))
    n, q = data[0], data[1]
    a = data[2:2 + n]
    qs = []
    p = 2 + n
    for _ in range(q):
        qs.append((data[p], data[p + 1]))
        p += 2
    for x in distinct_queries(a, qs):
