#include <bits/stdc++.h>
using namespace std;

struct BIT {
    int n;
    vector<int> t;
    BIT(int n = 0) { init(n); }
    void init(int n_) {
        n = n_;
        t.assign(n + 1, 0);
    }
    void add(int i, int d) {
        for (; i <= n; i += i & -i) t[i] += d;
    }
    int sum(int i) const {
        int s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    if (!(cin >> n >> q)) return 0;
    vector<int> a(n + 1);
    for (int i = 1; i <= n; ++i) cin >> a[i];
    vector<pair<int, int>> qs(q);
    for (int i = 0; i < q; ++i) cin >> qs[i].first >> qs[i].second;
    vector<int> order(q);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int x, int y) {
        return qs[x].second < qs[y].second;
    });
    BIT bit(n);
    unordered_map<int, int> last;
    vector<int> ans(q);
    int r = 0;
    for (int qi : order) {
        int l = qs[qi].first, qr = qs[qi].second;
        while (r < qr) {
            ++r;
            int v = a[r];
            auto it = last.find(v);
            if (it != last.end()) bit.add(it->second, -1);
            bit.add(r, 1);
            last[v] = r;
        }
        ans[qi] = bit.sum(qr) - bit.sum(l - 1);
    }
    for (int x : ans) cout << x << '\n';
    return 0;
}

