import sys


def solve():
    """本地模拟评测机：输入第一行是隐藏的 secret，ask(x) 代替真实提问。"""
    data = list(map(int, sys.stdin.read().split()))
    secret = data[0]

    def ask(x):
        # 真实交互题里这里是 print(x, flush=True) 然后读评测机返回
        if x < secret:
            return -1  # 猜小了
        if x > secret:
            return 1   # 猜大了
        return 0       # 猜中

    lo, hi = 1, 100
    cnt = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        cnt += 1
        r = ask(mid)
        if r == 0:
            print(secret, cnt)
            return
        if r < 0:
            lo = mid + 1
        else:
            hi = mid - 1


if __name__ == '__main__':
    solve()

