import sys


def knapsack_reachable(weights, W):
    """0/1 背包可行性：返回 <= W 的最大可达到和。"""
    bits = 1  # 第 i 位为 1 表示和 i 可达到
    for w in weights:
        bits |= bits << w
    for s in range(W, -1, -1):
        if bits >> s & 1:
            return s
    return 0


if __name__ == '__main__':
    data = list(map(int, sys.stdin.read().split()))
    n, W = data[0], data[1]
    weights = data[2:2 + n]
    print(knapsack_reachable(weights, W))

