#include <bits/stdc++.h>
using namespace std;
using int64 = long long;

int64 cdq_count(vector<int> &a, vector<int> &tmp, int l, int r) {
    // 统计 a[l..r) 的逆序对；返回后 a[l..r) 有序
    if (r - l <= 1) return 0;
    int mid = l + (r - l) / 2;
    int64 ans = cdq_count(a, tmp, l, mid) + cdq_count(a, tmp, mid, r);
    int i = l, j = mid, k = l;
    while (i < mid && j < r) {
        if (a[i] <= a[j]) {
            tmp[k++] = a[i++];
        } else {
            tmp[k++] = a[j++];
            ans += mid - i;
        }
    }
    while (i < mid) tmp[k++] = a[i++];
    while (j < r) tmp[k++] = a[j++];
    for (int t = l; t < r; ++t) a[t] = tmp[t];
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<int> a(n), tmp(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    cout << cdq_count(a, tmp, 0, n) << '\n';
    return 0;
}

