import sys

sys.setrecursionlimit(1 << 25)


def rec_sum(n):
    # 演示：深递归求 1+2+...+n。默认递归上限 1000，n=10000 会 RecursionError。
    if n == 0:
        return 0
    return n + rec_sum(n - 1)


def iter_sum(n):
    # 根治：改迭代，深度再大也不怕
    s = 0
    for i in range(1, n + 1):
        s += i
    return s


if __name__ == '__main__':
    data = list(map(int, sys.stdin.read().split()))
    n = data[0]
    # 两个版本结果一致；竞赛里优先用迭代版
    assert rec_sum(n) == iter_sum(n)
    print(iter_sum(n))

